// Generated by `just generate` from `src/plugins/claudetto/slices/handoff/lab/compaction.test.ts`. Edit the source and run `just generate`.
// Lab tests of the `handoff` `session.compact` hook (design D3, spec `handoff`).
// The stubs answer the fork, the session model, the write, and the stat of the hook,
// and the stub of `session.compact` is the built-in compaction, which gives a skip that names it.

import type { ModelForkResult, On, SessionMessage } from "claude-code";
import { type Engine, expect, mock, test } from "claude-code/testing";
import { FIRST_MESSAGE } from "../slices/handoff/prompts.ts";

const HANDOFF =
  // biome-ignore lint/plugin: test input data
  "- Read `a.txt` lines 1 to 600: DONE, line 1 is `amber-falcon-42`.\n- Next: read lines 601 to 1200.";
const BUILT_IN = "the built-in compaction";

/** A transcript of 6 messages that ends with an assistant reply, so the turn has ended and there is no tail. */
const MESSAGES: SessionMessage[] = [
  {
    role: "user",
    text: "Read a.txt in two parts.",
    toolUses: [],
    handle: "h0",
  },
  { role: "assistant", text: "", toolUses: [], handle: "h1" },
  { role: "user", text: "", toolUses: [], toolResults: [], handle: "h2" },
  { role: "assistant", text: "", toolUses: [], handle: "h3" },
  { role: "user", text: "", toolUses: [], toolResults: [], handle: "h4" },
  { role: "assistant", text: "Done.", toolUses: [], handle: "h5" },
];
const tool = { tool_use_id: "t1", tool: "Read", input: { file_path: "a.txt" } };
const TRANSCRIPT = MESSAGES.map((m, i) =>
  i === 3 ? { ...m, toolUses: [tool] } : m,
);
/** The first 5 messages of `TRANSCRIPT`, in a turn: the tail is the last 2, from the last assistant message with a tool use. */
const IN_TURN = TRANSCRIPT.slice(0, 5);

const NO_USAGE = {
  input_tokens: 0,
  output_tokens: 0,
  cache_read_input_tokens: 0,
  cache_creation_input_tokens: 0,
};
const answered = (text: string) => ({
  isAnswered: true as const,
  text,
  usage: NO_USAGE,
});
const NOTHING = {
  isAnswered: false as const,
  reason: "nothing-to-fork" as const,
};

/** What the stubs answer: the fork, the session model or `"reject"`, and the size of the file or the code of a stat error. */
type World = {
  fork?: ModelForkResult;
  model?: string;
  /** A fork that throws, as an SDK error does. */
  isForkThrowing?: boolean;
  stat?: number | "ENOENT" | "EACCES";
};

/** What the hook did: the writes, as path and text, and the prompts of the forks. */
type Seen = { writes: string[][]; forks: string[] };

/** The stubs for `world`, and the stub of `session.compact`, which is the built-in compaction. */
const engine = (on: On, world: World = {}): Seen => {
  const seen: Seen = { writes: [], forks: [] };
  on("model.fork", (_$, e) => {
    seen.forks.push(e.prompt);
    if (world.isForkThrowing) throw new Error("sdk error");
    return { value: world.fork ?? answered(HANDOFF) };
  });
  on("session.model", () => {
    if (world.model === "reject") throw new Error("no session");
    return { value: world.model ?? "claude-haiku-5-5" };
  });
  on("fs.write", (_$, e) => {
    seen.writes.push([e.path, e.text]);
    return { value: undefined };
  });
  on("fs.stat", () => {
    const stat = world.stat ?? 100;
    if (typeof stat === "string")
      throw Object.assign(new Error(stat), { code: stat });
    return { value: { kind: "file", size: stat, mtimeMs: 0, isLink: false } };
  });
  on("session.compact", () => ({ skip: BUILT_IN }));
  return seen;
};

/** The result of an `auto` compaction of `messages` of the main thread in `world`. */
const compact = (
  $: Engine,
  on: On,
  world: World = {},
  messages: SessionMessage[] = IN_TURN,
) => {
  const seen = engine(on, world);
  return $.session
    .compact({ trigger: "auto", messages })
    .then((result) => ({ result, seen }));
};

// biome-ignore lint/plugin: a test name
test("an auto compaction gives one user message with the first user message and the handoff, and the tail", async ($: Engine, on: On) => {
  const { result, seen } = await compact($, on);
  const [path, text] = seen.writes[0] ?? [];
  expect(path).toMatch(/\/\.claudetto\/handoffs\/handoff-\d{8}T\d{6}Z\.md$/);
  expect(text).toBe(`${HANDOFF}\n`);
  const out = result.messages ?? [];
  expect(out.map((m) => m.handle)).toEqual([undefined, "h3", "h4"]);
  expect(out[0]?.role).toBe("user");
  expect(out[0]?.text).toStartWith(
    FIRST_MESSAGE({ first: "Read a.txt in two parts.", handed: "" }),
  );
  const rel = (path as string).slice((path as string).indexOf(".claudetto/"));
  expect(out[0]?.text).toContain(`from \`${rel}\``);
  expect(out[0]?.text).toContain(text as string);
});

// biome-ignore lint/plugin: a test name
test("a manual compaction after the end of a turn gives one user message with the first user message and the handoff, and no tail", async ($: Engine, on: On) => {
  const seen = engine(on);
  const result = await $.session.compact({
    trigger: "manual",
    messages: TRANSCRIPT,
  });
  expect(result.messages?.map((m) => m.handle)).toEqual([undefined]);
  expect(seen.forks[0]).not.toContain("the session ran these tool calls");
});

// biome-ignore lint/plugin: a test name
test("the fork prompt names each tool call of the tail and asks to mark it `RAN`", async ($: Engine, on: On) => {
  const { seen } = await compact($, on);
  expect(seen.forks).toHaveLength(1);
  expect(seen.forks[0]).toContain('- Read {"file_path":"a.txt"}');
  expect(seen.forks[0]).toContain("mark it `RAN, result after this handoff`");
});

test("the fork prompt cuts a long tool input", async ($: Engine, on: On) => {
  const long = { ...tool, input: { content: "y".repeat(1000) } };
  const messages = IN_TURN.map((m, i) =>
    i === 3 ? { ...m, toolUses: [long] } : m,
  );
  const { seen } = await compact($, on, {}, messages);
  expect(seen.forks[0]).toContain("y...");
  expect(seen.forks[0]).not.toContain("y".repeat(400));
});

const FALLBACKS: [string, World][] = [
  ["nothing to fork", { fork: NOTHING }],
  [
    "an empty reply of the fork",
    { fork: { isAnswered: false, reason: "empty-reply", usage: NO_USAGE } },
  ],
  [
    "an API error of the fork",
    {
      fork: {
        isAnswered: false,
        reason: "api-error",
        status: 529,
        error: "overloaded",
        usage: NO_USAGE,
      },
    },
  ],
  ["a fork that throws", { isForkThrowing: true }],
  ["a session model that rejects", { model: "reject" }],
  [
    "a fork text with no value in backticks",
    {
      fork: answered(
        "The Read call returned an error. I will retry step 1 once.",
      ),
    },
  ],
  ["a missing file", { stat: "ENOENT" }],
  ["a stat error", { stat: "EACCES" }],
  ["an empty file", { stat: 0 }],
];

for (const [name, world] of FALLBACKS)
  test(`${name} gives the compaction to Claude Code`, async ($: Engine, on: On) => {
    const { result } = await compact($, on, world);
    expect(result.skip).toBe(BUILT_IN);
  });

test("a subagent compaction passes on with no change", async ($: Engine, on: On) => {
  const seen = engine(on);
  const result = await $.session.compact({
    trigger: "auto",
    agentId: "a1",
    messages: TRANSCRIPT,
  });
  expect(result.skip).toBe(BUILT_IN);
  expect(seen.writes).toEqual([]);
});

test("a `precompute` compaction passes on with no change", async ($: Engine, on: On) => {
  const seen = engine(on);
  const result = await $.session.compact({
    trigger: "precompute",
    messages: TRANSCRIPT,
  });
  expect(result.skip).toBe(BUILT_IN);
  expect(seen.writes).toEqual([]);
});

/** A transcript whose tail has two reads in one assistant message, with a result of `tokens` estimated tokens each. */
const bigTail = (tokens: number): SessionMessage[] => {
  const text = "x".repeat(tokens * 4);
  const read = (id: string, file_path: string) => ({
    tool_use_id: id,
    tool: "Read",
    input: { file_path },
    text,
  });
  return [
    MESSAGES[0] as SessionMessage,
    {
      role: "assistant",
      text: "",
      toolUses: [read("r1", "a.txt"), read("r2", "b.txt")],
      handle: "t1",
    },
    {
      role: "user",
      text: "",
      toolUses: [],
      toolResults: [
        { tool_use_id: "r1", text, isError: false },
        { tool_use_id: "r2", text, isError: false },
      ],
      handle: "t2",
    },
  ];
};

// biome-ignore lint/plugin: a test name
test("a tail of 120,000 tokens below the trigger of an Opus session stays whole", async ($: Engine, on: On) => {
  const world = { model: "claude-opus-5-5" };
  const { result } = await compact($, on, world, bigTail(60_000));
  expect(result.messages?.map((m) => m.handle)).toEqual([
    undefined,
    "t1",
    "t2",
  ]);
});

test("a tail above the trigger gives the compaction to Claude Code", async ($: Engine, on: On) => {
  const { result, seen } = await compact($, on, {}, bigTail(60_000));
  expect(result.skip).toBe(BUILT_IN);
  expect(seen.writes).toEqual([]);
});

/** `bigTail` with its two reads in two assistant messages, as Claude Code keeps the blocks of one reply. */
const splitTail = (tokens: number): SessionMessage[] => {
  const [first, reply, results] = bigTail(tokens) as [
    SessionMessage,
    SessionMessage,
    SessionMessage,
  ];
  return [
    first,
    { ...reply, toolUses: reply.toolUses.slice(0, 1), handle: "s1" },
    { ...reply, toolUses: reply.toolUses.slice(1), handle: "s2" },
    results,
  ];
};

// biome-ignore lint/plugin: a test name
test("a reply in two assistant messages stays whole in the tail, so each tool result keeps its call", async ($: Engine, on: On) => {
  const { result, seen } = await compact($, on, {}, splitTail(10));
  expect(result.messages?.map((m) => m.handle)).toEqual([
    undefined,
    "s1",
    "s2",
    "t2",
  ]);
  expect(seen.forks[0]).toContain('- Read {"file_path":"a.txt"}');
  expect(seen.forks[0]).toContain('- Read {"file_path":"b.txt"}');
});

// D23: a shell in a subfolder does not move the handoff, which goes under the project root.
// biome-ignore lint/plugin: a test name
test("a compaction with the shell in a subfolder writes the handoff under the project root", async ($: Engine, on: On) => {
  mock.env(on, { CLAUDE_PROJECT_DIR: "/p" });
  on("session.cwd", () => ({ value: "/p/openspec/changes/c" }));
  const { seen } = await compact($, on);
  const [path] = seen.writes[0] ?? [];
  expect(path).toMatch(
    /^\/p\/\.claudetto\/handoffs\/handoff-\d{8}T\d{6}Z\.md$/,
  );
});
